import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { z } from "zod";
import { AgentDocZ } from "../src/schema.js";
import { loadAtlas } from "../src/atlas.js";

// The agent.json contract (#169). `fixtures/emitted` is GENERATED by the Julia emitter
// (test/test_contract.jl regenerates it and fails on drift), so these tests check the consumer
// against what Pinax actually writes rather than a hand-written sample.
const here = dirname(fileURLToPath(import.meta.url));
const emitted = resolve(here, "../../test/fixtures/emitted");
const raw = JSON.parse(readFileSync(resolve(emitted, "agent.json"), "utf8"));

// Every object key in `value` that `schema` does not name, as dotted paths. The schema is
// `.passthrough()` so an OLDER consumer survives a newer emitter — which is exactly why a key the
// emitter writes and the schema forgot would otherwise go unnoticed.
function unnamedKeys(schema: z.ZodType, value: unknown, path: string): string[] {
  // walk the schema by its definition (zod 4: `_zod.def`), unwrapping lazy / optional / nullable
  const def = (schema as any)._zod.def;
  switch (def.type) {
    case "lazy":
      return unnamedKeys(def.getter(), value, path);
    case "pipe": // a refined and transformed object: walk what it reads
      return unnamedKeys(def.in, value, path);
    case "optional":
    case "nullable":
      return value == null ? [] : unnamedKeys(def.innerType, value, path);
    case "array":
      return Array.isArray(value)
        ? value.flatMap((v, i) => unnamedKeys(def.element, v, `${path}[${i}]`))
        : [];
    case "object": {
      if (value === null || typeof value !== "object") return [];
      const shape = def.shape as Record<string, z.ZodType>;
      return Object.entries(value as Record<string, unknown>).flatMap(([k, v]) =>
        k in shape ? unnamedKeys(shape[k], v, `${path}.${k}`) : [`${path}.${k}`],
      );
    }
    default:
      return []; // a scalar, a union of scalars, a record of params, or z.unknown()
  }
}

test("the emitted fixture parses against the schema", () => {
  const r = AgentDocZ.safeParse(raw);
  assert.ok(r.success, r.success ? "" : JSON.stringify(r.error.issues, null, 2));
});

test("the schema names every key the emitter writes", () => {
  assert.deepEqual(unnamedKeys(AgentDocZ, raw, "$"), []);
});

test("every content ref in the emitted fixture resolves to a unit", () => {
  const atlas = loadAtlas(emitted);
  const missing: string[] = [];
  const walk = (c: { content?: { kind: string; id: string }[]; sections?: unknown[] }) => {
    for (const ref of c.content ?? []) if (!atlas.unit(ref.id)) missing.push(`${ref.kind}:${ref.id}`);
    for (const s of c.sections ?? []) walk(s as typeof c);
  };
  atlas.doc.pages.forEach(walk);
  assert.deepEqual(missing, []);
});

test("the outline ends with the document's diagnostics", () => {
  const o = loadAtlas(emitted).outline();
  assert.match(o, /## Diagnostics\n- \[ERROR\] p2_fig_\w+: materialize failed/);
});

// The emitted fixture, changed by `change` (a deep copy; `raw` stays as Pinax wrote it).
const changed = (change: (doc: any) => void): unknown => {
  const doc = structuredClone(raw);
  change(doc);
  return doc;
};

test("the schema holds the small sets the emitter writes to them", () => {
  assert.ok(AgentDocZ.safeParse(changed((d) => (d.diagnostics = [{ severity: "WARNING", item: "x", message: "m" }]))).success);
  assert.ok(AgentDocZ.safeParse(changed((d) => (d.diagnostics = [{ severity: "INFO", item: "x", message: "m" }]))).success);
  assert.equal(AgentDocZ.safeParse(changed((d) => (d.diagnostics = [{ severity: "FATAL", item: "x", message: "m" }]))).success, false);
  assert.equal(AgentDocZ.safeParse(changed((d) => d.pages[0].content.push({ kind: "picture", id: "x" }))).success, false);
  assert.equal(AgentDocZ.safeParse(changed((d) => d.pages[0].sections[0].content.push({ kind: "picture", id: "x" }))).success, false);
  assert.equal(AgentDocZ.safeParse(changed((d) => (d.pages[0].status = "published"))).success, false);
  assert.equal(AgentDocZ.safeParse(changed((d) => (firstCheck(d).kind = "auto"))).success, false);
});

// The first check in the document, depth first.
const firstCheck = (doc: any): any => {
  const walk = (c: any): any => c.checks?.[0] ?? (c.sections ?? []).map(walk).find(Boolean);
  return doc.pages.map(walk).find(Boolean);
};

test("every emitted check states its outcome, and pass is derived from it", () => {
  const doc = AgentDocZ.parse(raw);
  const all = (c: any): any[] => [...(c.checks ?? []), ...(c.sections ?? []).flatMap(all)];
  const checks = doc.pages.flatMap(all);
  assert.ok(checks.length > 0);
  for (const c of checks) assert.equal(c.pass, c.outcome === "pass");
  assert.equal(AgentDocZ.safeParse(changed((d) => (firstCheck(d).outcome = "maybe"))).success, false);
});

test("the outline leads each check with its outcome, an error included", () => {
  const o = loadAtlas(emitted).outline();
  assert.match(o, /\] ERROR error\("boom"\)/);
  assert.match(o, /\] FAIL isapprox\(0\.5, 0\.0/);
});

test("an indicator check carries no numbers", () => {
  const doc = AgentDocZ.parse(raw);
  const all = (c: any): any[] => [...(c.checks ?? []), ...(c.sections ?? []).flatMap(all)];
  const ind = doc.pages.flatMap(all).filter((c) => c.kind === "indicator");
  assert.ok(ind.length > 0);
  for (const c of ind) assert.deepEqual([c.got, c.want, c.delta, c.tol], [null, null, null, null]);
});

test("a 0.1 page status 'trial' reads as 'draft'", () => {
  const doc = AgentDocZ.parse(changed((d) => (d.pages[0].status = "trial")));
  assert.equal(doc.pages[0].status, "draft");
});

test("the key walk reaches a check's own keys", () => {
  const extra = changed((d) => (firstCheck(d).zqextra = 1));
  assert.ok(unnamedKeys(AgentDocZ, extra, "$").some((k) => k.endsWith(".zqextra")));
});

test("a check's kind, outcome, pass and numbers agree, or it does not parse", () => {
  const refused = (change: (c: any) => void, why: RegExp) => {
    const r = AgentDocZ.safeParse(changed((d) => change(firstCheck(d))));
    assert.equal(r.success, false);
    assert.match(r.error!.issues.map((i) => i.message).join("\n"), why);
  };
  // the first check is a passing "rel" check with all four numbers
  refused((c) => (c.pass = false), /contradicts outcome/);
  refused((c) => ((c.outcome = "error"), (c.pass = true)), /contradicts outcome/);
  refused((c) => (c.kind = "indicator"), /an indicator check has null got, want, delta and tol/);
  refused((c) => (c.tol = null), /a "rel" check needs got, want, delta and tol/);
  refused((c) => ((c.kind = "abs"), (c.got = null)), /a "abs" check needs got, want, delta and tol/);
  // a non-finite number is written as a string, and is still a number
  assert.ok(AgentDocZ.safeParse(changed((d) => (firstCheck(d).tol = "Inf"))).success);
});

test("a check written before outcome existed reads its outcome from pass", () => {
  const doc = AgentDocZ.parse(
    changed((d) => {
      const c = firstCheck(d);
      delete c.outcome;
      c.pass = false;
    }),
  );
  assert.equal(firstCheck(doc).outcome, "fail");
  const passing = AgentDocZ.parse(changed((d) => delete firstCheck(d).outcome));
  assert.equal(firstCheck(passing).outcome, "pass");
});
